// Junta en un solo texto: tu perfil + las preguntas que YA respondiste.
// Ese texto es lo que Claude lee para decidir si encajas y para escribir cada correo.
const perfil = $('Leer Perfil').all().map(i => i.json).find(r => r['Clave'] === 'principal');
if (!perfil) {
  throw new Error('No encontré tu perfil. Ejecuta primero el Flujo 1 (formulario del CV).');
}

const respondidas = $('Leer Preguntas').all()
  .map(i => i.json)
  .filter(r => r['Pregunta'] && String(r['Respuesta'] || '').trim() !== '');

let detalle = {};
try { detalle = JSON.parse(perfil['Perfil JSON'] || '{}'); } catch (e) {}

const perfilTexto = [
  `Nombre: ${perfil['Nombre']}`,
  `Email: ${perfil['Email']}`,
  `Resumen: ${perfil['Resumen']}`,
  `Cargos objetivo: ${perfil['Cargos objetivo']}`,
  `Habilidades: ${perfil['Habilidades']}`,
  `Idiomas: ${perfil['Idiomas']}`,
  `Años de experiencia: ${detalle.anos_experiencia ?? 'no indicado'}`,
  `Logros: ${(detalle.logros_clave || []).join(' | ')}`,
  `Modalidad deseada: ${perfil['Modalidad']} (Quito, Ecuador o remoto mundial)`,
  `Salario esperado (USD/mes): ${perfil['Salario esperado'] || 'no indicado'}`,
  '',
  'Respuestas adicionales del candidato:',
  ...respondidas.map(r => `- ${r['Pregunta']} → ${r['Respuesta']}`),
].join('\n');

const keywords = String(perfil['Keywords'] || '')
  .split(',').map(k => k.trim()).filter(Boolean)
  // Máximo 4 palabras: cada una gasta 2 búsquedas de JSearch (plan gratis = 200 al mes).
  .slice(0, 4);

return [{ json: { perfilTexto, keywords, modalidad: perfil['Modalidad'] || 'Ambos' } }];

// Un item por palabra clave. Cada nodo de búsqueda que sigue se ejecuta
// una vez por cada item, o sea, una búsqueda por palabra clave.
const { keywords, modalidad } = $json;
return keywords.map(keyword => ({ json: { keyword, modalidad } }));

// JSearch devuelve vacantes de LinkedIn, Indeed, Glassdoor, etc.
// Las convertimos al formato común que usan todas las fuentes.
const limpiar = (html) => String(html || '')
  .replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&')
  .replace(/\s+/g, ' ').trim().slice(0, 5000);
const salida = [];
for (const item of $input.all()) {
  for (const j of (item.json.data || [])) {
    salida.push({ json: {
      id: 'jsearch-' + j.job_id,
      fuente: j.job_publisher || 'JSearch',
      cargo: j.job_title,
      empresa: j.employer_name || '',
      ubicacion: [j.job_city, j.job_country].filter(Boolean).join(', ') || 'No indicada',
      modalidad: j.job_is_remote ? 'Remoto' : 'Presencial/Híbrido',
      link: j.job_apply_link || j.job_google_link || '',
      descripcion: limpiar(j.job_description),
      fecha: (j.job_posted_at_datetime_utc || '').slice(0, 10),
    }});
  }
}
return salida;

// JSearch devuelve vacantes de LinkedIn, Indeed, Glassdoor, etc.
// Las convertimos al formato común que usan todas las fuentes.
const limpiar = (html) => String(html || '')
  .replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&')
  .replace(/\s+/g, ' ').trim().slice(0, 5000);
const salida = [];
for (const item of $input.all()) {
  for (const j of (item.json.data || [])) {
    salida.push({ json: {
      id: 'jsearch-' + j.job_id,
      fuente: j.job_publisher || 'JSearch',
      cargo: j.job_title,
      empresa: j.employer_name || '',
      ubicacion: [j.job_city, j.job_country].filter(Boolean).join(', ') || 'No indicada',
      modalidad: j.job_is_remote ? 'Remoto' : 'Presencial/Híbrido',
      link: j.job_apply_link || j.job_google_link || '',
      descripcion: limpiar(j.job_description),
      fecha: (j.job_posted_at_datetime_utc || '').slice(0, 10),
    }});
  }
}
return salida;

// Remotive: portal de trabajos 100% remotos (API pública y gratuita).
const limpiar = (html) => String(html || '')
  .replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&')
  .replace(/\s+/g, ' ').trim().slice(0, 5000);
const salida = [];
for (const item of $input.all()) {
  for (const j of (item.json.jobs || [])) {
    salida.push({ json: {
      id: 'remotive-' + j.id,
      fuente: 'Remotive',
      cargo: j.title,
      empresa: j.company_name || '',
      ubicacion: j.candidate_required_location || 'Worldwide',
      modalidad: 'Remoto',
      link: j.url,
      descripcion: limpiar(j.description),
      fecha: (j.publication_date || '').slice(0, 10),
    }});
  }
}
return salida;

// RemoteOK devuelve una lista; el nodo HTTP la separa en un item por vacante.
// El primer elemento es un aviso legal (no tiene "position") y se descarta.
const limpiar = (html) => String(html || '')
  .replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&')
  .replace(/\s+/g, ' ').trim().slice(0, 5000);
const salida = [];
for (const item of $input.all()) {
  const j = item.json;
  if (!j.position || !j.url) continue;
  salida.push({ json: {
    id: 'remoteok-' + j.id,
    fuente: 'RemoteOK',
    cargo: j.position,
    empresa: j.company || '',
    ubicacion: j.location || 'Worldwide',
    modalidad: 'Remoto',
    link: j.apply_url || j.url,
    descripcion: limpiar(j.description),
    fecha: (j.date || '').slice(0, 10),
  }});
}
return salida;

// Upwork vía Apify. Cada actor de Apify nombra los campos un poco distinto,
// por eso probamos varios nombres posibles. Si el nodo Apify está desactivado,
// aquí llegan las palabras clave (sin link) y simplemente se descartan.
const limpiar = (html) => String(html || '')
  .replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&')
  .replace(/\s+/g, ' ').trim().slice(0, 5000);
const salida = [];
for (const item of $input.all()) {
  const j = item.json;
  const link = j.url || j.link || j.jobUrl || '';
  if (!link) continue;
  salida.push({ json: {
    id: 'upwork-' + (j.id || j.uid || link),
    fuente: 'Upwork',
    cargo: j.title || j.jobTitle || 'Proyecto Upwork',
    empresa: j.client?.country ? `Cliente de ${j.client.country}` : 'Cliente Upwork',
    ubicacion: 'Worldwide',
    modalidad: 'Remoto (freelance)',
    link,
    descripcion: limpiar(j.description || j.snippet),
    fecha: String(j.publishedAt || j.createdOn || j.date || '').slice(0, 10),
  }});
}
return salida;

// 1) Junta todas las fuentes  2) quita vacantes sin link o repetidas
// 3) quita las que YA están en tu hoja (para no pagar a Claude dos veces por la misma)
// 4) se queda con máximo 25 por ejecución para controlar el costo.
const MAX_POR_EJECUCION = 25;

const yaGuardadas = new Set(
  $('Leer Vacantes guardadas').all().map(i => String(i.json['ID'] || '')).filter(Boolean)
);
const linksGuardados = new Set(
  $('Leer Vacantes guardadas').all().map(i => String(i.json['Link'] || '')).filter(Boolean)
);

// Respeta la modalidad que elegiste en el formulario (Ambos / Solo Quito / Solo remoto)
const modalidad = $('Armar perfil').first().json.modalidad;
const esRemoto = v => String(v.modalidad).startsWith('Remoto');

const vistas = new Set();
const nuevas = [];
for (const item of $('Unir fuentes').all()) {
  const v = item.json;
  if (!v.link || !v.cargo) continue;
  const clave = v.link.split('?')[0];
  const claveTexto = `${v.cargo}|${v.empresa}`.toLowerCase();
  if (vistas.has(clave) || vistas.has(claveTexto)) continue;
  if (yaGuardadas.has(v.id) || linksGuardados.has(v.link)) continue;
  if (modalidad === 'Solo Quito' && esRemoto(v)) continue;
  if (modalidad === 'Solo remoto' && !esRemoto(v)) continue;
  vistas.add(clave); vistas.add(claveTexto);
  nuevas.push({ json: v });
}

// Las más recientes primero
nuevas.sort((a, b) => String(b.json.fecha).localeCompare(String(a.json.fecha)));
return nuevas.slice(0, MAX_POR_EJECUCION);

