// Une la vacante original con el análisis de Claude
// y arma la fila con los mismos nombres de columna que tu hoja "Vacantes".
const v = $('Quitar repetidas').item.json;
// Si Claude falló con esta vacante, r queda vacío y el filtro la descarta (Match 0).
const r = $json.output || {};

const preguntas = (r.preguntas_para_mi || []).map(p => '• ' + p).join('\n');

return {
  json: {
    'Fecha': $now.toFormat('yyyy-LL-dd'),
    'Fuente': v.fuente,
    'Cargo': v.cargo,
    'Empresa': v.empresa,
    'Ubicación': `${v.ubicacion} · ${v.modalidad}`,
    'Match %': Math.round(Number(r.match_score) || 0),
    'Por qué encajo': r.razon,
    'Link': v.link,
    'Email': r.email_contacto ? r.email_contacto : 'Aplicar por link',
    'Asunto': r.mail_asunto,
    'Mail': r.mail_cuerpo,
    'Preguntas para mí': preguntas,
    'Estado': 'Sin enviar',
    'Fecha envío': '',
    'ID': v.id,
    '_ubicacion_valida': r.ubicacion_valida === true,
  }
};

// Quita el campo auxiliar "_ubicacion_valida" (no es una columna de la hoja).
return $input.all().map(i => {
  const { _ubicacion_valida, ...fila } = i.json;
  return { json: fila };
});

// Arma el resumen que te llega por correo con los cargos a los que puedes aplicar.
const filas = $input.all().map(i => i.json);
const lineas = filas
  .sort((a, b) => b['Match %'] - a['Match %'])
  .map(f => `• [${f['Match %']}%] ${f['Cargo']} — ${f['Empresa']} (${f['Ubicación']})\n  ${f['Link']}`);

return [{
  json: {
    asunto: `🎯 ${filas.length} vacantes nuevas donde puedes aplicar`,
    cuerpo: [
      `Hola, encontré ${filas.length} vacantes que encajan con tu perfil:`,
      '',
      ...lineas,
      '',
      'Los correos ya están redactados en tu Google Sheet (pestaña "Vacantes").',
      'Revísalos, ajústalos, envíalos tú y cambia el Estado a "Enviado".',
    ].join('\n'),
  }
}];
